const b=$('Inspect Hook').first().json.body||{};
const rows=$input.all().map(i=>i.json);
function body(row){let h=row.content;try{const o=JSON.parse(row.content);if(o&&o.b)h=o.b;}catch(e){}return String(h||'').replace(/data:image\/[a-z]+;base64,[A-Za-z0-9+\/=]+/g,'[IMG]');}
if(b.list){return [{json:{pages:rows.filter(r=>!String(r.name).startsWith('_bak')).map(r=>({name:r.name,len:String(r.content||'').length}))}}];}
if(b.scanAll){const out={};const r=b.radius||150;for(const row of rows){if(String(row.name).startsWith('_bak'))continue;const h=body(row);for(const t of b.terms){let i=h.indexOf(t);const a=[];while(i>-1&&a.length<(b.maxHits||3)){a.push({at:i,s:h.slice(Math.max(0,i-r),i+t.length+r)});i=h.indexOf(t,i+1);}if(a.length){out[row.name]=out[row.name]||{};out[row.name][t]=a;}}}return [{json:{hits:out}}];}
const row=rows.find(r=>r.name===(b.page||'page:cbs-admin'));
if(!row)return [{json:{err:'no page'}}];
const h=body(row);
const out={len:h.length};
if(b.scriptId){const m=h.match(new RegExp('<script id="'+b.scriptId+'">([\\s\\S]*?)<\\/script>'));out.script=m?m[1].slice(b.from||0,(b.from||0)+(b.max||20000)):null;out.scriptLen=m?m[1].length:0;}
if(b.slice){out.slice=h.slice(b.slice[0],b.slice[1]);}
if(b.terms){const r=b.radius||300;out.hits={};for(const t of b.terms){const a=[];let i=h.indexOf(t);while(i>-1&&a.length<(b.maxHits||5)){a.push({at:i,s:h.slice(Math.max(0,i-r),i+t.length+r)});i=h.indexOf(t,i+1);}out.hits[t]=a;}}
if(b.ids){const m=h.match(/<script id="[^"]+">/g)||[];out.scriptIds=m;}
return [{json:out}];
